cypress_script:
describe('Accordion Functionality', () => {
  it('should expand the first accordion section', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').should('not.have.class', 'collapsed');
  });

  it('should not change URL when clicking on an already expanded section', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.url().should('eq', 'https://demoqa.com/accordian');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Accordion Functionality', () => {
  test('should expand the first accordion section', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    const button = await page.locator('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await expect(button).not.toHaveClass(/collapsed/);
  });

  test('should not change URL when clicking on an already expanded section', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await expect(page).toHaveURL('https://demoqa.com/accordian');
  });
});
